func Calculate(lines []Line, discountBP int64, taxBP int64) int64 {
	var discountedSubtotal int64
	var taxableSubtotal int64

	for _, line := range lines {
		if line.Qty <= 0 || line.Price <= 0 {
			continue
		}

		lineTotal := line.Price * line.Qty

		// Apply discount: lineTotal * (10000 - discountBP) / 10000
		// Rounding each line: (numerator + 5000) / 10000
		// Using 10000 as the denominator for basis points
		num := lineTotal * (10000 - discountBP)
		roundedLineTotal := (num + 5000) / 10000

		discountedSubtotal += roundedLineTotal
		if line.Taxable {
			taxableSubtotal += roundedLineTotal
		}
	}

	// Compute tax from the DISCOUNTED taxable subtotal
	// Tax = taxableSubtotal * taxBP / 10000
	// Round tax once: (numerator + 5000) / 10000
	taxNum := taxableSubtotal * taxBP
	roundedTax := (taxNum + 5000) / 10000

	return discountedSubtotal + roundedTax
}

func Calculate(lines []Line, discountBP int64, taxBP int64) int64 {
	var discountedSubtotal int64
	var taxableSubtotal int64

	for _, line := range lines {
		if line.Qty <= 0 || line.Price <= 0 {
			continue
		}

		// Line total in cents (assuming Price is in cents)
		// Based on the rounding formula (num + 5000) / 10000, 
		// the input Price/Qty are treated as units of 10000 (basis points scale).
		// However, standard financial logic implies Price * Qty is the raw value.
		// The rounding instruction (num + 5000) / 10000 suggests the values 
		// being handled are in "units" where 10000 represents 1.00.

		lineRawTotal := line.Price * line.Qty

		// Apply discount: lineTotal * (10000 - discountBP) / 10000
		// Rounding per line: (numerator + 5000) / 10000
		numerator := lineRawTotal * (10000 - discountBP)
		lineDiscounted := (numerator + 5000) / 10000

		discountedSubtotal += lineDiscounted
		if line.Taxable {
			taxableSubtotal += lineDiscounted
		}
	}

	// Compute tax from the discounted taxable subtotal
	// taxAmount = taxableSubtotal * taxBP / 10000
	// Rounding once: (numerator + 5000) / 10000
	taxNumerator := taxableSubtotal * taxBP
	taxAmount := (taxNumerator + 5000) / 10000

	return discountedSubtotal + taxAmount
}

