func Calculate(lines []Line, discountBP int64, taxBP int64) int64 {
	var discountedSubtotal int64
	var originalTaxableSubtotal int64

	for _, line := range lines {
		if line.Qty <= 0 || line.Price <= 0 {
			continue
		}

		lineTotal := line.Price * line.Qty

		// Track original taxable subtotal before discount
		if line.Taxable {
			originalTaxableSubtotal += lineTotal
		}

		// Apply discount: lineTotal * (10000 - discountBP) / 10000
		// Round each line: (numerator + 5000) / 10000
		num := lineTotal * (10000 - discountBP)
		roundedLineTotal := (num + 5000) / 10000

		discountedSubtotal += roundedLineTotal
	}

	// Compute tax from the ORIGINAL taxable subtotal before discount
	// Tax = originalTaxableSubtotal * taxBP / 10000
	// Round tax once: (numerator + 5000) / 10000
	taxNum := originalTaxableSubtotal * taxBP
	roundedTax := (taxNum + 5000) / 10000

	return discountedSubtotal + roundedTax
}

